			CasterProgression = CasterProgression.Pact,
			SpellcastingAbility = AbilityScore.Charisma,
			SubclassLevel = 3,
			Translations = new List<CharacterClassTranslation>
			{
				new CharacterClassTranslation
				{
					Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class", "warlock", "en"),
					Language = LanguageCode.En,
					Name = "Warlock",
					Description = "An occultist bound to a mysterious otherworldly patron. Warlocks seek forbidden knowledge, and their pact grants them a small but potent pool of magic that returns after a brief rest, along with eldritch invocations that reshape their abilities in strange and personal ways.",
					SubclassTitle = "Warlock Subclass",
					ArmorProficiencies = "Light armor",
					WeaponProficiencies = "Simple weapons",
					ToolProficiencies = "None",
					StartingEquipment = "Choose A or B:\n- (A) Leather Armor, Sickle, 2 Daggers, Arcane Focus (orb), Book (occult lore), Scholar's Pack and 15 GP\n- (B) 100 GP",
					ProgressionTable = "| Level | Proficiency Bonus | Class Features | Eldritch Invocations | Cantrips | Prepared Spells | Spell Slots | Slot Level |\n|---|---|---|---|---|---|---|---|\n| 1 | +2 | Eldritch Invocations, Pact Magic | 1 | 2 | 2 | 1 | 1 |\n| 2 | +2 | Magical Cunning | 3 | 2 | 3 | 2 | 1 |\n| 3 | +2 | Warlock Subclass | 3 | 2 | 4 | 2 | 2 |\n| 4 | +2 | Ability Score Improvement | 3 | 3 | 5 | 2 | 2 |\n| 5 | +3 | — | 5 | 3 | 6 | 2 | 3 |\n| 6 | +3 | Subclass feature | 5 | 3 | 7 | 2 | 3 |\n| 7 | +3 | — | 6 | 3 | 8 | 2 | 4 |\n| 8 | +3 | Ability Score Improvement | 6 | 3 | 9 | 2 | 4 |\n| 9 | +4 | Contact Patron | 7 | 3 | 10 | 2 | 5 |\n| 10 | +4 | Subclass feature | 7 | 4 | 10 | 2 | 5 |\n| 11 | +4 | Mystic Arcanum | 7 | 4 | 11 | 3 | 5 |\n| 12 | +4 | Ability Score Improvement | 8 | 4 | 11 | 3 | 5 |\n| 13 | +5 | Mystic Arcanum | 8 | 4 | 12 | 3 | 5 |\n| 14 | +5 | Subclass feature | 8 | 4 | 12 | 3 | 5 |\n| 15 | +5 | Mystic Arcanum | 9 | 4 | 13 | 3 | 5 |\n| 16 | +5 | Ability Score Improvement | 9 | 4 | 13 | 3 | 5 |\n| 17 | +6 | Mystic Arcanum | 9 | 4 | 14 | 4 | 5 |\n| 18 | +6 | — | 10 | 4 | 14 | 4 | 5 |\n| 19 | +6 | Epic Boon | 10 | 4 | 15 | 4 | 5 |\n| 20 | +6 | Eldritch Master | 10 | 4 | 15 | 4 | 5 |"
				},
				new CharacterClassTranslation
				{
					Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class", "warlock", "it"),
					Language = LanguageCode.It,
					Name = "Warlock",
					Description = "Un occultista legato a un misterioso patrono ultraterreno. Il warlock va in cerca di conoscenze proibite, e il suo patto gli conferisce una riserva di magia piccola ma potente, che si rinnova dopo un breve riposo, insieme a suppliche occulte che rimodellano le sue capacità in modi strani e personali.",
					SubclassTitle = "Sottoclasse del warlock",
					ArmorProficiencies = "Armature leggere",
					WeaponProficiencies = "Armi semplici",
					ToolProficiencies = "Nessuno",
					StartingEquipment = "A scelta tra A e B:\n- (A) un'armatura di cuoio, un falcetto, 2 pugnali, un focus arcano (sfera), un libro (sapere occulto), una dotazione da studioso e 15 mo\n- (B) 100 mo",
					ProgressionTable = "| Livello | Bonus di competenza | Privilegi di classe | Suppliche occulte | Trucchetti | Incantesimi preparati | Slot incantesimo | Livello degli slot |\n|---|---|---|---|---|---|---|---|\n| 1 | +2 | Suppliche Occulte, Magia del Patto | 1 | 2 | 2 | 1 | 1 |\n| 2 | +2 | Scaltrezza Magica | 3 | 2 | 3 | 2 | 1 |\n| 3 | +2 | Sottoclasse del Warlock | 3 | 2 | 4 | 2 | 2 |\n| 4 | +2 | Aumento dei Punteggi di Caratteristica | 3 | 3 | 5 | 2 | 2 |\n| 5 | +3 | — | 5 | 3 | 6 | 2 | 3 |\n| 6 | +3 | Privilegio della sottoclasse | 5 | 3 | 7 | 2 | 3 |\n| 7 | +3 | — | 6 | 3 | 8 | 2 | 4 |\n| 8 | +3 | Aumento dei Punteggi di Caratteristica | 6 | 3 | 9 | 2 | 4 |\n| 9 | +4 | Contatta Patrono | 7 | 3 | 10 | 2 | 5 |\n| 10 | +4 | Privilegio della sottoclasse | 7 | 4 | 10 | 2 | 5 |\n| 11 | +4 | Arcanum Mistico | 7 | 4 | 11 | 3 | 5 |\n| 12 | +4 | Aumento dei Punteggi di Caratteristica | 8 | 4 | 11 | 3 | 5 |\n| 13 | +5 | Arcanum Mistico | 8 | 4 | 12 | 3 | 5 |\n| 14 | +5 | Privilegio della sottoclasse | 8 | 4 | 12 | 3 | 5 |\n| 15 | +5 | Arcanum Mistico | 9 | 4 | 13 | 3 | 5 |\n| 16 | +5 | Aumento dei Punteggi di Caratteristica | 9 | 4 | 13 | 3 | 5 |\n| 17 | +6 | Arcanum Mistico | 9 | 4 | 14 | 4 | 5 |\n| 18 | +6 | — | 10 | 4 | 14 | 4 | 5 |\n| 19 | +6 | Dono Epico | 10 | 4 | 15 | 4 | 5 |\n| 20 | +6 | Maestro dell'Occulto | 10 | 4 | 15 | 4 | 5 |"
				}
			},
			Features = new List<ClassFeature>
			{
				new ClassFeature
				{
					Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "warlock/eldritch-invocations"),
					Ruleset = RulesetVersion.Dnd5e_2024,
					Level = 1,
					SortOrder = 0,
					Translations = new List<ClassFeatureTranslation>
					{
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "warlock/eldritch-invocations", "en"), Language = LanguageCode.En, Name = "Eldritch Invocations", Description = "You have unearthed Eldritch Invocations, pieces of forbidden knowledge that imbue you with an abiding magical ability or other lessons. You gain one invocation of your choice, such as Pact of the Tome. Invocations are described in the “Eldritch Invocation Options” section later in this class’s description.\n\n**Prerequisites.** If an invocation has a prerequisite, you must meet it to learn that invocation. For example, if an invocation requires you to be a level 5+ Warlock, you can select the invocation once you reach Warlock level 5.\n\n**Replacing and Gaining Invocations.** Whenever you gain a Warlock level, you can replace one of your invocations with another one for which you qualify. You can’t replace an invocation if it’s a prerequisite for another invocation that you have.\n\nWhen you gain certain Warlock levels, you gain more invocations of your choice, as shown in the Invocations column of the Warlock Features table.\n\nYou can’t pick the same invocation more than once unless its description says otherwise.\n\n**Eldritch Invocation Options**\n\nThe invocations appear in alphabetical order.\n\n**Agonizing Blast.** *Prerequisite: Level 2+ Warlock, a Warlock Cantrip That Deals Damage.* Choose one of your known Warlock cantrips that deals damage. You can add your Charisma modifier to that spell's damage rolls. *Repeatable:* you can gain this invocation more than once; each time you do so, choose a different eligible cantrip.\n\n**Armor of Shadows.** You can cast *Mage Armor* on yourself without expending a spell slot.\n\n**Ascendant Step.** *Prerequisite: Level 5+ Warlock.* You can cast *Levitate* on yourself without expending a spell slot.\n\n**Devil's Sight.** *Prerequisite: Level 2+ Warlock.* You can see normally in Dim Light and Darkness, both magical and nonmagical, within 120 feet of yourself.\n\n**Devouring Blade.** *Prerequisite: Level 12+ Warlock, Thirsting Blade Invocation.* The Extra Attack of your Thirsting Blade invocation confers two extra attacks rather than one.\n\n**Eldritch Mind.** You have Advantage on Constitution saving throws that you make to maintain Concentration.\n\n**Eldritch Smite.** *Prerequisite: Level 5+ Warlock, Pact of the Blade Invocation.* Once per turn when you hit a creature with your pact weapon, you can expend a Pact Magic spell slot to deal an extra 1d8 Force damage to the target, plus another 1d8 per level of the spell slot, and you can give the target the Prone condition if it is Huge or smaller.\n\n**Eldritch Spear.** *Prerequisite: Level 2+ Warlock, a Warlock Cantrip That Deals Damage.* Choose one of your known Warlock cantrips that deals damage and has a range of 10+ feet. When you cast that spell, its range increases by a number of feet equal to 30 times your Warlock level. *Repeatable:* you can gain this invocation more than once; each time you do so, choose a different eligible cantrip.\n\n**Fiendish Vigor.** *Prerequisite: Level 2+ Warlock.* You can cast *False Life* on yourself without expending a spell slot. When you cast the spell with this feature, you don't roll the die for the Temporary Hit Points; you automatically get the highest number on the die.\n\n**Gaze of Two Minds.** *Prerequisite: Level 5+ Warlock.* You can use a Bonus Action to touch a willing creature and perceive through its senses until the end of your next turn. As long as the creature is on the same plane of existence as you, you can take a Bonus Action on subsequent turns to maintain this connection, extending the duration until the end of your next turn. The connection ends if you don't maintain it in this way. While perceiving through the other creature's senses, you benefit from any special senses possessed by that creature, and you can cast spells as if you were in your space or the other creature's space if the two of you are within 60 feet of each other.\n\n**Gift of the Depths.** *Prerequisite: Level 5+ Warlock.* You can breathe underwater, and you gain a Swim Speed equal to your Speed. You can also cast *Water Breathing* once without expending a spell slot. You regain the ability to cast it in this way again when you finish a Long Rest.\n\n**Gift of the Protectors.** *Prerequisite: Level 9+ Warlock, Pact of the Tome Invocation.* A new page appears in your Book of Shadows when you conjure it. With your permission, a creature can take an action to write its name on that page, which can contain a number of names equal to your Charisma modifier (minimum of one name). When any creature whose name is on the page is reduced to 0 Hit Points but not killed outright, the creature magically drops to 1 Hit Point instead. Once this magic is triggered, no creature can benefit from it until you finish a Long Rest. As a Magic action, you can erase a name on the page by touching it.\n\n**Investment of the Chain Master.** *Prerequisite: Level 5+ Warlock, Pact of the Chain Invocation.* When you cast *Find Familiar*, you infuse the summoned familiar with a measure of your eldritch power, granting the creature the following benefits. *Aerial or Aquatic:* the familiar gains either a Fly Speed or a Swim Speed (your choice) of 40 feet. *Quick Attack:* as a Bonus Action, you can command the familiar to take the Attack action. *Necrotic or Radiant Damage:* whenever the familiar deals Bludgeoning, Piercing, or Slashing damage, you can make it deal Necrotic or Radiant damage instead. *Your Save DC:* if the familiar forces a creature to make a saving throw, it uses your spell save DC. *Resistance:* when the familiar takes damage, you can take a Reaction to grant it Resistance against that damage.\n\n**Lessons of the First Ones.** *Prerequisite: Level 2+ Warlock.* You have received knowledge from an elder entity of the multiverse, allowing you to gain one Origin feat of your choice. *Repeatable:* you can gain this invocation more than once; each time you do so, choose a different Origin feat.\n\n**Lifedrinker.** *Prerequisite: Level 9+ Warlock, Pact of the Blade Invocation.* Once per turn when you hit a creature with your pact weapon, you can deal an extra 1d6 Necrotic, Psychic, or Radiant damage (your choice) to the creature, and you can expend one of your Hit Point Dice to roll it and regain a number of Hit Points equal to the roll plus your Constitution modifier (minimum of 1 Hit Point).\n\n**Mask of Many Faces.** *Prerequisite: Level 2+ Warlock.* You can cast *Disguise Self* without expending a spell slot.\n\n**Master of Myriad Forms.** *Prerequisite: Level 5+ Warlock.* You can cast *Alter Self* without expending a spell slot.\n\n**Misty Visions.** *Prerequisite: Level 2+ Warlock.* You can cast *Silent Image* without expending a spell slot.\n\n**One with Shadows.** *Prerequisite: Level 5+ Warlock.* While you're in an area of Dim Light or Darkness, you can cast *Invisibility* on yourself without expending a spell slot.\n\n**Otherworldly Leap.** *Prerequisite: Level 2+ Warlock.* You can cast *Jump* on yourself without expending a spell slot.\n\n**Pact of the Blade.** As a Bonus Action, you can conjure a pact weapon in your hand (a Simple or Martial Melee weapon of your choice with which you bond) or create a bond with a magic weapon you touch; you can't bond with a magic weapon if someone else is attuned to it or another Warlock is bonded with it. Until the bond ends, you have proficiency with the weapon, and you can use it as a Spellcasting Focus. Whenever you attack with the bonded weapon, you can use your Charisma modifier for the attack and damage rolls instead of using Strength or Dexterity; and you can cause the weapon to deal Necrotic, Psychic, or Radiant damage or its normal damage type. Your bond with the weapon ends if you use this feature's Bonus Action again, if the weapon is more than 5 feet away from you for 1 minute or more, or if you die. A conjured weapon disappears when the bond ends.\n\n**Pact of the Chain.** You learn the *Find Familiar* spell and can cast it as a Magic action without expending a spell slot. When you cast the spell, you choose one of the normal forms for your familiar or one of the following special forms: Imp, Pseudodragon, Quasit, Skeleton, Slaad Tadpole, Sphinx of Wonder, Sprite, or Venomous Snake. Additionally, when you take the Attack action, you can forgo one of your own attacks to allow your familiar to make one attack of its own with its Reaction.\n\n**Pact of the Tome.** Stitching together strands of shadow, you conjure forth a book in your hand at the end of a Short or Long Rest. This Book of Shadows (you determine its appearance) contains eldritch magic that only you can access, granting you the benefits below. The book disappears if you conjure another book with this feature or if you die. *Cantrips and Rituals:* when the book appears, choose three cantrips, and choose two level 1 spells that have the Ritual tag. The spells can be from any class's spell list, and they must be spells you don't already have prepared. While the book is on your person, you have the chosen spells prepared, and they function as Warlock spells for you. *Spellcasting Focus:* you can use the book as a Spellcasting Focus.\n\n**Repelling Blast.** *Prerequisite: Level 2+ Warlock, a Warlock Cantrip That Deals Damage via an Attack Roll.* Choose one of your known Warlock cantrips that requires an attack roll. When you hit a Large or smaller creature with that cantrip, you can push the creature up to 10 feet straight away from you. *Repeatable:* you can gain this invocation more than once; each time you do so, choose a different eligible cantrip.\n\n**Thirsting Blade.** *Prerequisite: Level 5+ Warlock, Pact of the Blade Invocation.* You gain the Extra Attack feature for your pact weapon only. With that feature, you can attack twice with the weapon instead of once when you take the Attack action on your turn.\n\n**Visions of Distant Realms.** *Prerequisite: Level 9+ Warlock.* You can cast *Arcane Eye* without expending a spell slot.\n\n**Whispers of the Grave.** *Prerequisite: Level 7+ Warlock.* You can cast *Speak with Dead* without expending a spell slot.\n\n**Witch Sight.** *Prerequisite: Level 15+ Warlock.* You have Truesight with a range of 30 feet." },
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "warlock/eldritch-invocations", "it"), Language = LanguageCode.It, Name = "Suppliche Occulte", Description = "Il warlock ha portato alla luce le suppliche occulte, frammenti di conoscenza proibita che gli conferiscono una capacità magica permanente o altri insegnamenti. Ottiene una supplica a sua scelta, come Patto del tomo; le suppliche sono descritte di seguito.\n\n**Prerequisiti.** Se una supplica ha un prerequisito, il warlock deve soddisfarlo per apprenderla. Per esempio, se una supplica richiede un warlock di 5° livello o superiore, può sceglierla quando raggiunge il 5° livello da warlock.\n\n**Sostituire e ottenere suppliche.** Ogni volta che sale di livello come warlock, può sostituire una delle sue suppliche con un'altra di cui soddisfa i prerequisiti. Non può sostituire una supplica che è prerequisito di un'altra supplica che possiede.\n\nA determinati livelli da warlock ottiene altre suppliche a sua scelta, come indicato nella colonna Suppliche occulte della tabella dei privilegi del warlock.\n\nIl warlock non può scegliere la stessa supplica più di una volta, a meno che la sua descrizione non dica diversamente.\n\n**Opzioni di suppliche occulte**\n\nLe suppliche sono elencate in ordine alfabetico secondo il loro nome inglese.\n\n**Deflagrazione agonizzante.** *Prerequisito: warlock di 2° livello o superiore, un trucchetto da warlock che infligge danni.* Il warlock sceglie uno dei trucchetti da warlock che conosce e che infligge danni: può sommare il suo modificatore di Carisma ai tiri per i danni di quell'incantesimo. *Ripetibile:* può ottenere questa supplica più volte, scegliendo ogni volta un trucchetto idoneo diverso.\n\n**Armatura delle ombre.** Il warlock può lanciare *armatura magica* su se stesso senza spendere uno slot incantesimo.\n\n**Passo ascendente.** *Prerequisito: warlock di 5° livello o superiore.* Il warlock può lanciare *levitazione* su se stesso senza spendere uno slot incantesimo.\n\n**Vista del diavolo.** *Prerequisito: warlock di 2° livello o superiore.* Il warlock vede normalmente nella luce fioca e nell'oscurità, magica e non magica, entro 36 metri da lui.\n\n**Lama divoratrice.** *Prerequisito: warlock di 12° livello o superiore, supplica Lama assetata.* L'Attacco extra della supplica Lama assetata conferisce due attacchi extra anziché uno.\n\n**Mente occulta.** Il warlock dispone di vantaggio ai tiri salvezza su Costituzione per mantenere la concentrazione.\n\n**Punizione occulta.** *Prerequisito: warlock di 5° livello o superiore, supplica Patto della lama.* Una volta per turno, quando colpisce una creatura con la sua arma del patto, il warlock può spendere uno slot incantesimo della Magia del patto per infliggere al bersaglio 1d8 danni da forza extra, più 1d8 per ogni livello dello slot, e, se il bersaglio è di taglia Enorme o inferiore, può fargli subire la condizione di prono.\n\n**Lancia occulta.** *Prerequisito: warlock di 2° livello o superiore, un trucchetto da warlock che infligge danni.* Il warlock sceglie uno dei trucchetti da warlock che conosce, che infligge danni e ha una gittata di almeno 3 metri: quando lo lancia, la sua gittata aumenta di 9 metri per ogni livello da warlock. *Ripetibile:* può ottenere questa supplica più volte, scegliendo ogni volta un trucchetto idoneo diverso.\n\n**Vigore immondo.** *Prerequisito: warlock di 2° livello o superiore.* Il warlock può lanciare *vita falsata* su se stesso senza spendere uno slot incantesimo. Quando lo lancia con questo privilegio, non tira il dado per i punti ferita temporanei, ma ottiene automaticamente il risultato massimo.\n\n**Sguardo delle due menti.** *Prerequisito: warlock di 5° livello o superiore.* Il warlock può usare un'azione bonus per toccare una creatura consenziente e percepire attraverso i suoi sensi fino alla fine del suo turno successivo. Finché la creatura si trova sul suo stesso piano di esistenza, nei turni seguenti può usare un'azione bonus per mantenere il collegamento, estendendone la durata fino alla fine del turno successivo; se non lo mantiene, il collegamento termina. Mentre percepisce attraverso i sensi dell'altra creatura, beneficia dei suoi sensi speciali e, se i due si trovano entro 18 metri l'uno dall'altra, può lanciare incantesimi come se si trovasse nel proprio spazio o in quello dell'altra creatura.\n\n**Dono degli abissi.** *Prerequisito: warlock di 5° livello o superiore.* Il warlock può respirare sott'acqua e ottiene una velocità di nuotare pari alla sua velocità. Può inoltre lanciare *respirare sott'acqua* una volta senza spendere uno slot incantesimo, e riacquista questa possibilità quando completa un riposo lungo.\n\n**Dono del protettore.** *Prerequisito: warlock di 9° livello o superiore, supplica Patto del tomo.* Quando il warlock evoca il suo Libro delle ombre, vi compare una nuova pagina. Con il suo permesso, una creatura può usare un'azione per scrivervi il proprio nome; la pagina può contenere un numero di nomi pari al modificatore di Carisma del warlock (minimo uno). Quando una creatura il cui nome è sulla pagina scende a 0 punti ferita senza morire sul colpo, scende invece magicamente a 1 punto ferita; una volta attivata questa magia, nessuna creatura può beneficiarne finché il warlock non completa un riposo lungo. Con un'azione di Magia, il warlock può cancellare un nome dalla pagina toccandolo.\n\n**Investitura del signore delle catene.** *Prerequisito: warlock di 5° livello o superiore, supplica Patto della catena.* Quando lancia *trova famiglio*, il warlock infonde nel famiglio evocato parte del suo potere occulto, conferendogli i benefici seguenti. *Volo o nuoto:* il famiglio ottiene una velocità di volare o di nuotare (a scelta del warlock) di 12 metri. *Attacco rapido:* come azione bonus, il warlock può ordinare al famiglio di effettuare l'azione di Attacco. *Danni necrotici o radiosi:* ogni volta che il famiglio infligge danni contundenti, perforanti o taglienti, il warlock può fargli infliggere invece danni necrotici o radiosi. *CD del warlock:* se il famiglio costringe una creatura a un tiro salvezza, usa la CD del tiro salvezza degli incantesimi del warlock. *Resistenza:* quando il famiglio subisce danni, il warlock può usare una reazione per conferirgli resistenza contro quei danni.\n\n**Conoscenza degli antichi.** *Prerequisito: warlock di 2° livello o superiore.* Il warlock ha ricevuto conoscenze da un'entità primordiale del multiverso e ottiene un talento delle origini a sua scelta. *Ripetibile:* può ottenere questa supplica più volte, scegliendo ogni volta un talento delle origini diverso.\n\n**Succhiavita.** *Prerequisito: warlock di 9° livello o superiore, supplica Patto della lama.* Una volta per turno, quando colpisce una creatura con la sua arma del patto, il warlock può infliggerle 1d6 danni necrotici, psichici o radiosi extra (a sua scelta) e può spendere uno dei suoi Dadi Vita, tirarlo e recuperare punti ferita pari al risultato + il suo modificatore di Costituzione (minimo 1 punto ferita).\n\n**Maschera dei molti volti.** *Prerequisito: warlock di 2° livello o superiore.* Il warlock può lanciare *camuffare se stesso* senza spendere uno slot incantesimo.\n\n**Maestro di mille forme.** *Prerequisito: warlock di 5° livello o superiore.* Il warlock può lanciare *alterare se stesso* senza spendere uno slot incantesimo.\n\n**Visioni velate.** *Prerequisito: warlock di 2° livello o superiore.* Il warlock può lanciare *immagine silenziosa* senza spendere uno slot incantesimo.\n\n**Tutt'uno con le ombre.** *Prerequisito: warlock di 5° livello o superiore.* Mentre si trova in un'area di luce fioca o di oscurità, il warlock può lanciare *invisibilità* su se stesso senza spendere uno slot incantesimo.\n\n**Balzo ultraterreno.** *Prerequisito: warlock di 2° livello o superiore.* Il warlock può lanciare *saltare* su se stesso senza spendere uno slot incantesimo.\n\n**Patto della lama.** Come azione bonus, il warlock può evocare nella propria mano un'arma del patto, un'arma da mischia semplice o da guerra a sua scelta a cui si vincola, oppure creare un legame con un'arma magica che tocca; non può vincolarsi a un'arma magica con cui qualcun altro è in sintonia o a cui è vincolato un altro warlock. Finché il legame dura, il warlock ha competenza nell'arma e può usarla come focus da incantatore. Ogni volta che attacca con l'arma vincolata, può usare il suo modificatore di Carisma per i tiri per colpire e per i danni anziché la Forza o la Destrezza, e può farle infliggere danni necrotici, psichici o radiosi oppure il suo tipo di danni normale. Il legame termina se il warlock usa di nuovo l'azione bonus di questo privilegio, se l'arma rimane a più di 1,5 metri da lui per 1 minuto o più, o se muore. Un'arma evocata scompare quando il legame termina.\n\n**Patto della catena.** Il warlock impara l'incantesimo *trova famiglio* e può lanciarlo con un'azione di Magia senza spendere uno slot incantesimo. Quando lo lancia, sceglie per il famiglio una delle forme normali oppure una delle forme speciali seguenti: drago fatato, folletto, girino di slaad, imp, quasit, scheletro, serpente velenoso o sfinge delle meraviglie. Inoltre, quando effettua l'azione di Attacco, può rinunciare a uno dei propri attacchi per permettere al famiglio di effettuare un attacco con la sua reazione.\n\n**Patto del tomo.** Intrecciando filamenti d'ombra, al termine di un riposo breve o lungo il warlock evoca un libro nella propria mano. Questo Libro delle ombre (di cui sceglie l'aspetto) contiene una magia occulta accessibile solo a lui e gli conferisce i benefici seguenti; il libro scompare se il warlock ne evoca un altro con questo privilegio o se muore. *Trucchetti e rituali:* quando il libro compare, il warlock sceglie tre trucchetti e due incantesimi di 1° livello con il descrittore rituale, da qualsiasi lista di incantesimi, che non ha già preparati; finché ha il libro con sé, ha preparati quegli incantesimi, che per lui contano come incantesimi da warlock. *Focus da incantatore:* il warlock può usare il libro come focus da incantatore.\n\n**Deflagrazione respingente.** *Prerequisito: warlock di 2° livello o superiore, un trucchetto da warlock che infligge danni tramite un tiro per colpire.* Il warlock sceglie uno dei trucchetti da warlock che conosce e che richiede un tiro per colpire: quando colpisce con esso una creatura di taglia Grande o inferiore, può spingerla fino a 3 metri in linea retta lontano da sé. *Ripetibile:* può ottenere questa supplica più volte, scegliendo ogni volta un trucchetto idoneo diverso.\n\n**Lama assetata.** *Prerequisito: warlock di 5° livello o superiore, supplica Patto della lama.* Il warlock ottiene il privilegio Attacco extra, ma soltanto per la sua arma del patto: con esso, quando effettua l'azione di Attacco nel suo turno, può attaccare due volte con l'arma anziché una.\n\n**Visione dei reami lontani.** *Prerequisito: warlock di 9° livello o superiore.* Il warlock può lanciare *occhio arcano* senza spendere uno slot incantesimo.\n\n**Sussurri dalla tomba.** *Prerequisito: warlock di 7° livello o superiore.* Il warlock può lanciare *parlare con i morti* senza spendere uno slot incantesimo.\n\n**Vista stregata.** *Prerequisito: warlock di 15° livello o superiore.* Il warlock ha vista pura con un raggio di 9 metri." }
					}
				},
				new ClassFeature
				{
					Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "warlock/pact-magic"),
					Ruleset = RulesetVersion.Dnd5e_2024,
					Level = 1,
					SortOrder = 1,
					Translations = new List<ClassFeatureTranslation>
					{
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "warlock/pact-magic", "en"), Language = LanguageCode.En, Name = "Pact Magic", Description = "Through occult ceremony, you have formed a pact with a mysterious entity to gain magical powers. The entity is a voice in the shadows—its identity unclear—but its boon to you is concrete: the ability to cast spells. See chapter 7 for the rules on spellcasting. The information below details how you use those rules with Warlock spells, which appear in the Warlock spell list later in the class’s description.\n\n**Cantrips.** You know two Warlock cantrips of your choice. Eldritch Blast and Prestidigitation are recommended. Whenever you gain a Warlock level, you can replace one of your cantrips from this feature with another Warlock cantrip of your choice.\n\nWhen you reach Warlock levels 4 and 10, you learn another Warlock cantrip of your choice, as shown in the Cantrips column of the Warlock Features table.\n\n**Spell Slots.** The Warlock Features table shows how many spell slots you have to cast your Warlock spells of levels 1–5. The table also shows the level of those slots, all of which are the same level. You regain all expended Pact Magic spell slots when you finish a Short or Long Rest.\n\nFor example, when you’re a level 5 Warlock, you have two level 3 spell slots. To cast the level 1 spell Witch Bolt, you must spend one of those slots, and you cast it as a level 3 spell.\n\n**Prepared Spells of Level 1+.** You prepare the list of level 1+ spells that are available for you to cast with this feature. To start, choose two level 1 Warlock spells. Charm Person and Hex are recommended.\n\nThe number of spells on your list increases as you gain Warlock levels, as shown in the Prepared Spells column of the Warlock Features table. Whenever that number increases, choose additional Warlock spells until the number of spells on your list matches the number in the table. The chosen spells must be of a level no higher than what’s shown in the table’s Slot Level column for your level. When you reach level 6, for example, you learn a new Warlock spell, which can be of levels 1–3.\n\nIf another Warlock feature gives you spells that you always have prepared, those spells don’t count against the number of spells you can prepare with this feature, but those spells otherwise count as Warlock spells for you.\n\n**Changing Your Prepared Spells.** Whenever you gain a Warlock level, you can replace one spell on your list with another Warlock spell of an eligible level.\n\n**Spellcasting Ability.** Charisma is the spellcasting ability for your Warlock spells.\n\n**Spellcasting Focus.** You can use an Arcane Focus as a Spellcasting Focus for your Warlock spells." },
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "warlock/pact-magic", "it"), Language = LanguageCode.It, Name = "Magia del Patto", Description = "Con una cerimonia occulta, il warlock ha stretto un patto con un'entità misteriosa per ottenere poteri magici. L'entità è una voce nell'ombra, dall'identità incerta, ma il suo dono è concreto: la capacità di lanciare incantesimi (le regole per lanciarli si trovano nel capitolo sugli incantesimi). Di seguito è spiegato come il warlock applica quelle regole agli incantesimi da warlock, che compaiono nella lista degli incantesimi da warlock.\n\n**Trucchetti.** Il warlock conosce due trucchetti da warlock a sua scelta; sono consigliati *deflagrazione occulta* e *prestidigitazione*. Ogni volta che sale di livello come warlock, può sostituire uno dei trucchetti ottenuti con questo privilegio con un altro trucchetto da warlock a sua scelta. Al 4° e al 10° livello da warlock impara un altro trucchetto da warlock a sua scelta, come indicato nella colonna Trucchetti della tabella dei privilegi del warlock.\n\n**Slot incantesimo.** La tabella dei privilegi del warlock indica quanti slot incantesimo possiede il warlock per lanciare i suoi incantesimi da warlock di livello da 1 a 5, e il livello di quegli slot, che sono tutti dello stesso livello. Il warlock recupera tutti gli slot incantesimo della Magia del patto spesi quando completa un riposo breve o lungo. Per esempio, un warlock di 5° livello ha due slot incantesimo di 3° livello: per lanciare l'incantesimo di 1° livello *dardo stregato* deve spendere uno di quegli slot, e lo lancia come incantesimo di 3° livello.\n\n**Incantesimi preparati di 1° livello o superiore.** Il warlock prepara l'elenco degli incantesimi di 1° livello o superiore che può lanciare con questo privilegio. Per cominciare, sceglie due incantesimi da warlock di 1° livello; sono consigliati *charme su persone* e *sortilegio*.\n\nIl numero di incantesimi del suo elenco aumenta man mano che sale di livello come warlock, come indicato nella colonna Incantesimi preparati della tabella dei privilegi del warlock. Ogni volta che quel numero aumenta, sceglie altri incantesimi da warlock finché il numero di incantesimi nel suo elenco non coincide con quello della tabella. Gli incantesimi scelti devono essere di un livello non superiore a quello indicato nella colonna Livello degli slot della tabella per il suo livello; per esempio, al 6° livello impara un nuovo incantesimo da warlock, che può essere di livello da 1 a 3.\n\nSe un altro privilegio da warlock gli fa avere incantesimi sempre preparati, quegli incantesimi non contano nel numero di incantesimi che può preparare con questo privilegio, ma per il resto contano come incantesimi da warlock per lui.\n\n**Cambiare gli incantesimi preparati.** Ogni volta che sale di livello come warlock, può sostituire un incantesimo del suo elenco con un altro incantesimo da warlock di un livello idoneo.\n\n**Caratteristica da incantatore.** Il Carisma è la caratteristica da incantatore per i suoi incantesimi da warlock.\n\n**Focus da incantatore.** Il warlock può usare un focus arcano come focus da incantatore per i suoi incantesimi da warlock." }
					}
				},
				new ClassFeature
				{
					Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "warlock/magical-cunning"),
					Ruleset = RulesetVersion.Dnd5e_2024,
					Level = 2,
					SortOrder = 2,
					Translations = new List<ClassFeatureTranslation>
					{
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "warlock/magical-cunning", "en"), Language = LanguageCode.En, Name = "Magical Cunning", Description = "You can perform an esoteric rite for 1 minute. At the end of it, you regain expended Pact Magic spell slots but no more than a number equal to half your maximum (round up). Once you use this feature, you can’t do so again until you finish a Long Rest." },
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "warlock/magical-cunning", "it"), Language = LanguageCode.It, Name = "Scaltrezza Magica", Description = "Il warlock può celebrare un rito esoterico della durata di 1 minuto. Al termine, recupera slot incantesimo della Magia del patto spesi, fino a un massimo pari alla metà del suo numero massimo di slot (arrotondata per eccesso). Dopo aver usato questo privilegio, non può farlo di nuovo finché non completa un riposo lungo." }
					}
				},
				new ClassFeature
				{
					Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "warlock/warlock-subclass"),
					Ruleset = RulesetVersion.Dnd5e_2024,
					Level = 3,
					SortOrder = 3,
					Translations = new List<ClassFeatureTranslation>
					{
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "warlock/warlock-subclass", "en"), Language = LanguageCode.En, Name = "Warlock Subclass", Description = "You gain a Warlock subclass of your choice. The Archfey Patron, Celestial Patron, Fiend Patron, and Great Old One Patron subclasses are detailed after this class’s description. A subclass is a specialization that grants you features at certain Warlock levels. For the rest of your career, you gain each of your subclass’s features that are of your Warlock level or lower." },
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "warlock/warlock-subclass", "it"), Language = LanguageCode.It, Name = "Sottoclasse del Warlock", Description = "Il warlock ottiene una sottoclasse del warlock a sua scelta: Patrono Celestiale, Patrono Grande Antico, Patrono Immondo o Patrono Signore Fatato. Una sottoclasse è una specializzazione che conferisce privilegi a determinati livelli da warlock. Per il resto della sua carriera, il warlock ottiene ogni privilegio della sottoclasse di livello pari o inferiore al suo livello da warlock." }
					}
				},
				new ClassFeature
				{
					Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "warlock/ability-score-improvement"),
					Ruleset = RulesetVersion.Dnd5e_2024,
					Level = 4,
					SortOrder = 4,
					Translations = new List<ClassFeatureTranslation>
					{
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "warlock/ability-score-improvement", "en"), Language = LanguageCode.En, Name = "Ability Score Improvement", Description = "You gain the Ability Score Improvement feat (see chapter 5) or another feat of your choice for which you qualify. You gain this feature again at Warlock levels 8, 12, and 16." },
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "warlock/ability-score-improvement", "it"), Language = LanguageCode.It, Name = "Aumento dei Punteggi di Caratteristica", Description = "Il warlock ottiene il talento Aumento dei punteggi di caratteristica o un altro talento a sua scelta di cui soddisfa i prerequisiti. Ottiene di nuovo questo privilegio all'8°, al 12° e al 16° livello da warlock." }
					}
				},
				new ClassFeature
				{
					Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "warlock/contact-patron"),
					Ruleset = RulesetVersion.Dnd5e_2024,
					Level = 9,
					SortOrder = 5,
					Translations = new List<ClassFeatureTranslation>
					{
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "warlock/contact-patron", "en"), Language = LanguageCode.En, Name = "Contact Patron", Description = "In the past, you usually contacted your patron through intermediaries. Now you can communicate directly; you always have the Contact Other Plane spell prepared. With this feature, you can cast the spell without expending a spell slot to contact your patron, and you automatically succeed on the spell's saving throw.\n\nOnce you cast the spell with this feature, you can't do so in this way again until you finish a Long Rest." },
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "warlock/contact-patron", "it"), Language = LanguageCode.It, Name = "Contatta Patrono", Description = "In passato il warlock entrava in contatto con il suo patrono di solito tramite intermediari; ora può comunicare direttamente. Ha sempre preparato l'incantesimo *contattare altri piani* e, con questo privilegio, può lanciarlo senza spendere uno slot incantesimo per mettersi in contatto con il suo patrono, superando automaticamente il tiro salvezza dell'incantesimo.\n\nDopo aver lanciato l'incantesimo con questo privilegio, non può farlo di nuovo in questo modo finché non completa un riposo lungo." }
					}
				},
				new ClassFeature
				{
					Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "warlock/mystic-arcanum"),
					Ruleset = RulesetVersion.Dnd5e_2024,
					Level = 11,
					SortOrder = 6,
					Translations = new List<ClassFeatureTranslation>
					{
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "warlock/mystic-arcanum", "en"), Language = LanguageCode.En, Name = "Mystic Arcanum", Description = "Your patron grants you a magical secret called an arcanum. Choose one level 6 Warlock spell as this arcanum.\n\nYou can cast your arcanum spell once without expending a spell slot, and you must finish a Long Rest before you can cast it in this way again.\n\nAs shown in the Warlock Features table, you gain another Warlock spell of your choice that can be cast in this way when you reach Warlock levels 13 (level 7 spell), 15 (level 8 spell), and 17 (level 9 spell). You regain all uses of your Mystic Arcanum when you finish a Long Rest. Whenever you gain a Warlock level, you can replace one of your arcanum spells with another Warlock spell of the same level." },
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "warlock/mystic-arcanum", "it"), Language = LanguageCode.It, Name = "Arcanum Mistico", Description = "Il patrono del warlock gli concede un segreto magico chiamato arcanum. Il warlock sceglie un incantesimo da warlock di 6° livello come arcanum.\n\nPuò lanciare l'incantesimo del suo arcanum una volta senza spendere uno slot incantesimo, e deve completare un riposo lungo prima di poterlo lanciare di nuovo in questo modo.\n\nCome indicato nella tabella dei privilegi del warlock, ottiene un altro incantesimo da warlock a sua scelta lanciabile in questo modo al 13° (incantesimo di 7° livello), al 15° (8° livello) e al 17° livello da warlock (9° livello). Recupera tutti gli utilizzi di Arcanum mistico quando completa un riposo lungo. Ogni volta che sale di livello come warlock, può sostituire uno degli incantesimi del suo arcanum con un altro incantesimo da warlock dello stesso livello." }
					}
				},
				new ClassFeature
				{
					Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "warlock/epic-boon"),
					Ruleset = RulesetVersion.Dnd5e_2024,
					Level = 19,
					SortOrder = 7,
					Translations = new List<ClassFeatureTranslation>
					{
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "warlock/epic-boon", "en"), Language = LanguageCode.En, Name = "Epic Boon", Description = "You gain an Epic Boon feat (see chapter 5) or another feat of your choice for which you qualify. Boon of Fate is recommended." },
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "warlock/epic-boon", "it"), Language = LanguageCode.It, Name = "Dono Epico", Description = "Il warlock ottiene un talento Dono epico o un altro talento a sua scelta di cui soddisfa i prerequisiti. È consigliato il Dono del fato." }
