					Level = 20,
					SortOrder = 8,
					Translations = new List<ClassFeatureTranslation>
					{
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "warlock/eldritch-master", "en"), Language = LanguageCode.En, Name = "Eldritch Master", Description = "When you use your Magical Cunning feature, you regain all your expended Pact Magic spell slots." },
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "warlock/eldritch-master", "it"), Language = LanguageCode.It, Name = "Maestro dell'Occulto", Description = "Quando usa Scaltrezza magica, il warlock recupera tutti gli slot incantesimo della Magia del patto spesi." }
